use std::env;
use std::path::Path;

let input_path = env::var("INPUT_PATH").expect("INPUT_PATH not set");
let output_format = env::var("OUTPUT_FORMAT").expect("OUTPUT_FORMAT not set");
if !Path::new(&input_path).exists() {
    panic!("Input file does not exist");
}
let computed_output_path = {
    let p = Path::new(&input_path);
    let stem = p.file_stem().unwrap().to_string_lossy();
    format!("{}.{}", stem, output_format)
};

use api2convert::Api2Convert;
let client = Api2Convert::from_env().expect("Failed to create client");
let result = client.convert(&input_path, &output_format).expect("Conversion failed");
let saved_path = result.save(".", None).expect("Saving result failed");
let output_path = saved_path.to_string_lossy().to_string();
